CREATE TABLE deployments (id VARCHAR(36) PRIMARY KEY, strategy_version_id VARCHAR(36) NOT NULL REFERENCES strategy_versions(id), target_environment VARCHAR(16) NOT NULL, target_reference VARCHAR(160) NOT NULL, status VARCHAR(32) NOT NULL, config_checksum VARCHAR(64) NOT NULL, config_text VARCHAR(8000) NOT NULL, config_path VARCHAR(1024) NOT NULL, acknowledgement JSON, previous_deployment_id VARCHAR(36) REFERENCES deployments(id), deployed_at TIMESTAMP, acknowledged_at TIMESTAMP, created_at TIMESTAMP NOT NULL);
